def build_editor():
    """Recupera el editor integrado sin acceder al sistema de archivos."""
    return zlib.decompress(base64.b85decode(_EDITOR)).decode("utf-8")


def main():
    import streamlit as st
    import streamlit.components.v1 as components
    st.set_page_config(page_title="SlideStudio", page_icon="🖼️", layout="wide", initial_sidebar_state="collapsed")
    st.markdown('<style>.block-container{max-width:100%;padding:1rem .65rem .5rem;}[data-testid="stHeader"]{height:0;background:transparent;}iframe{border:0;}</style>', unsafe_allow_html=True)
    components.html(build_editor(), height=1220, scrolling=True)


if __name__ == "__main__":
    main()
